from pathlib import Path
import json,hashlib,shutil,subprocess,re
root=Path.cwd();s=root/'.local/step07-ci-timeout';out=root/'docs/evidence/step-07/ci-timeout';source=json.loads((s/'source-freeze.json').read_text())['sourceSHA'];out.mkdir(parents=True,exist_ok=False);sha=lambda b:hashlib.sha256(b).hexdigest();origins=[]
def textclean(t):
 return re.sub(r'postgres(?:ql)?://[^\s\"\']+', '<PRIVATE_OWN_DATABASE_URL>',re.sub(r'tileset_step07_[a-f0-9]{32}','<OWN_NEW_TEST_DATABASE>',t.replace(str(root),'<CODING_WORKTREE>')))
def capture(p,target,exact=False):
 raw=p.read_bytes();q=out/target;q.parent.mkdir(parents=True,exist_ok=True)
 if exact:shutil.copyfile(p,q)
 elif p.suffix in ['.log','.py','.ts','.mjs']:
  q.write_text(json.dumps({'privateOriginal':str(p.relative_to(root)),'originalSHA256':sha(raw),'originalBytes':len(raw),'text':textclean(raw.decode()),'sanitized':True},indent=2)+'\n')
 else:q.write_text(textclean(raw.decode()))
 origins.append({'privateOriginal':str(p.relative_to(root)),'originalSHA256':sha(raw),'originalBytes':len(raw),'evidenceCopy':str(q.relative_to(out)),'evidenceSHA256':sha(q.read_bytes()),'evidenceBytes':q.stat().st_size,'exact':exact})
for p in sorted(s.iterdir()):
 if not p.is_file() or p.name in ['runtime-private.json','progress-before-timeout-freeze.json','protected-before-freeze.json']:continue
 if p.suffix=='.json':capture(p,'results/'+p.name)
 elif p.suffix in ['.log','.py','.ts']:capture(p,'raw/'+p.name+'.json')
for p in sorted((s/'final').glob('*')):
 if p.is_file() and p.suffix=='.json':capture(p,'final/'+p.name)
 elif p.is_file() and p.suffix=='.log':capture(p,'final/'+p.name+'.json')
w=root/json.loads((s/'final/workspace.json').read_text())['workspace']
for d in sorted(w.glob('.local/step07/tests/*')):
 own=d/'ownership.json'
 if not own.exists() or json.loads(own.read_text())['sourceContext']['commit']!=source:continue
 folder = 'latest-http' if (d/'r4-duplicate-legacy.json').exists() else 'latest-controlled'
 for p in sorted(d.glob('r4-*')):
  if p.is_file() and p.suffix in ['.json','.png']:capture(p,folder+'/'+p.name,exact=p.suffix=='.png')
manifest=next(w.glob('artifacts/step07-'+source[:12]+'*/manifest.json'));capture(manifest,'engineering-manifest.json',exact=True)
# Keep baseline failures and real traces private, publish SHA inventory and timing records without database ownership values.
oldW=Path(json.loads((s/'runtime-private.json').read_text())['workspace']);baseline=[]
for d in sorted(oldW.glob('.local/step07/tests/*')):
 for p in sorted(d.glob('r4-*')):
  if p.is_file():baseline.append({'path':str(p.relative_to(root)),'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size})
  if p.is_file() and p.name in ['r4-diagnostic-events.json','r4-diagnostic-progress.json','r4-ui-timing.json']:capture(p,'baseline-records/'+d.name+'/'+p.name)
(out/'retained-baseline-artifacts.json').write_text(json.dumps({'sourceBaseline':'87e13a8a99db3058dce8680d3ae985969b8a9bac','files':baseline,'originalFailuresAndTraceNotDeleted':True},indent=2)+'\n')
(out/'original-file-provenance.json').write_text(json.dumps({'sourceSHA':source,'files':origins,'privateData':'Credentials/.env/database ownership/dumps/assets/browser trace ZIP remain private; raw original SHA/bytes mapped here'},indent=2)+'\n')
print('Evidence collected',len(origins),'original bindings')
